return items.map(item => {
  const fromNumber = $input.first().json.body.From;

  item.json.cleaned_number = String(fromNumber).replace('+', '');

  return item;
});

return items.map(item => {
  const rawNumber = item.json.From || item.json.number || '';

  // Remove everything except digits
  let digits = String(rawNumber).replace(/\D/g, '');

  // Remove US country code if present
  if (digits.length === 11 && digits.startsWith('1')) {
    digits = digits.slice(1);
  }

  // Convert to (904) 000-0000 format
  const formattedNumber = digits.replace(
    /^(\d{3})(\d{3})(\d{4})$/,
    '($1) $2-$3'
  );

  return {
    json: {
      ...item.json,
      formatted_number: formattedNumber
    }
  };
});

