return items.filter(item => {
  const cellValue = String(item.json["All Numbers"] || "");
  const searchNumber = String($('Convert Number into Sheet Format Number 850').first().json.formatted_number || "");

  const numbers = cellValue
    .split(",")
    .map(n => n.trim());

  return numbers.includes(searchNumber);
});

